#!/bin/sh
# make 首次构建：依赖图驱动的完整编译链路
# 期望输出见 expected_output（本机 MinGW 工具链 + GNU Make 真实执行捕获）

cat > Makefile << 'EOF'
CC := D:/mingw64/bin/gcc.exe
CFLAGS := -std=c11 -O2 -Wall
TARGET := app.exe
OBJS := main.o util.o

$(TARGET): $(OBJS)
	$(CC) $(CFLAGS) -o $@ $^

%.o: %.c
	$(CC) $(CFLAGS) -c $< -o $@

.PHONY: clean status
clean:
	@rm -f $(TARGET) $(OBJS)

status:
	@echo "artifacts: [$(wildcard *.o)] [$(wildcard *.d)]"
EOF

cat > main.c << 'EOF'
#include <stdio.h>
#include "util.h"

int main(void)
{
    printf("add(2, 3) = %d\n", add(2, 3));
    return 0;
}
EOF

cat > util.c << 'EOF'
#include "util.h"

int add(int a, int b)
{
    return a + b;
}
EOF

cat > util.h << 'EOF'
int add(int a, int b);
EOF

mingw32-make status     # 构建前：无产物
mingw32-make            # 首次构建：两个 .o + 链接
mingw32-make status     # 构建后：产物清单
./app
